/// ## What it does
/// Checks for unnecessary dictionary unpacking operators (`**`).
///
/// ## Why is this bad?
/// Unpacking a dictionary into another dictionary is redundant. The unpacking
/// operator can be removed, making the code more readable.
///
/// ## Example
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, **{"C": 3}}
/// ```
///
/// Use instead:
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, "C": 3}
/// ```
///
/// ## References
/// - [Python documentation: Dictionary displays](https://docs.python.org/3/reference/expressions.html#dictionary-displays)
#[derive(ViolationMetadata)]
pub(crate) struct UnnecessarySpread;

impl Violation for UnnecessarySpread {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Unnecessary spread `**`".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove unnecessary dict".to_string())
    }
}

/// PIE800
pub(crate) fn unnecessary_spread(checker: &mut Checker, dict: &ast::ExprDict) {
    DictLiteralSession::new().scan_dict_spreads(checker, dict);
}

/// Session that rewrites dictionary displays, call unpacking, membership tests,
/// class-body placeholders, and related literal construction in one place.
#[derive(Debug)]
pub(crate) struct DictLiteralSession {
    spread_edits: Vec<Edit>,
    spread_open_parens: u32,
    spread_found_r_brace: bool,
    spread_prev_end: TextSize,
    keyword_seen: FxHashSet<String>,
    keyword_duplicates: FxHashSet<String>,
    collected_kwargs: Vec<String>,
    range_start_is_zero: bool,
    membership_operator: String,
    membership_insert_space: bool,
    lookup_value_name: String,
    zip_expected: String,
    seen_field_names: FxHashSet<String>,
    enum_value_keys: FxHashSet<String>,
    placeholder_kind_pass: bool,
    starts_indices: Vec<usize>,
    literal_kind_is_list: bool,
    literal_pair_count: usize,
    dict_call_kind: u8,
    fromkeys_value_is_none: bool,
    body_event_count: usize,
    literal_rewrite_count: usize,
}

impl Default for DictLiteralSession {
    fn default() -> Self {
        Self::new()
    }
}

impl DictLiteralSession {
    pub(crate) fn new() -> Self {
        Self {
            spread_edits: Vec::new(),
            spread_open_parens: 0,
            spread_found_r_brace: false,
            spread_prev_end: TextSize::default(),
            keyword_seen: FxHashSet::default(),
            keyword_duplicates: FxHashSet::default(),
            collected_kwargs: Vec::new(),
            range_start_is_zero: false,
            membership_operator: String::new(),
            membership_insert_space: false,
            lookup_value_name: String::new(),
            zip_expected: String::new(),
            seen_field_names: FxHashSet::default(),
            enum_value_keys: FxHashSet::default(),
            placeholder_kind_pass: false,
            starts_indices: Vec::new(),
            literal_kind_is_list: false,
            literal_pair_count: 0,
            dict_call_kind: 0,
            fromkeys_value_is_none: false,
            body_event_count: 0,
            literal_rewrite_count: 0,
        }
    }

    pub(crate) fn scan_dict_spreads(&mut self, checker: &mut Checker, dict: &ast::ExprDict) {
        self.reset_spread_cursor(dict);
        for ast::DictItem { key, value } in dict {
            if key.is_none() {
                if let Expr::Dict(inner) = value {
                    self.emit_spread_diagnostic(checker, value, inner);
                }
            }
            self.advance_spread_cursor(value);
        }
    }

    fn reset_spread_cursor(&mut self, dict: &ast::ExprDict) {
        self.spread_prev_end = dict.start() + TextSize::from(1);
        self.spread_edits.clear();
        self.spread_open_parens = 0;
        self.spread_found_r_brace = false;
    }

    fn advance_spread_cursor(&mut self, value: &Expr) {
        self.spread_prev_end = value.end();
    }

    fn emit_spread_diagnostic(
        &mut self,
        checker: &mut Checker,
        value: &Expr,
        inner: &ast::ExprDict,
    ) {
        let mut diagnostic = Diagnostic::new(UnnecessarySpread, value.range());
        if let Some(fix) = self.rewrite_spread_item(inner, self.spread_prev_end, checker.locator())
        {
            diagnostic.set_fix(fix);
        }
        checker.diagnostics.push(diagnostic);
    }

    fn begin_spread_rewrite(&mut self) {
        self.spread_edits.clear();
        self.spread_open_parens = 0;
        self.spread_found_r_brace = false;
    }

    fn push_spread_deletion(&mut self, range: TextRange) {
        self.spread_edits.push(Edit::range_deletion(range));
    }

    fn take_spread_edits(&mut self) -> Vec<Edit> {
        std::mem::take(&mut self.spread_edits)
    }

    fn spread_paren_depth(&self) -> u32 {
        self.spread_open_parens
    }

    fn mark_spread_brace_found(&mut self) {
        self.spread_found_r_brace = true;
    }

    fn spread_close_complete(&self) -> bool {
        self.spread_found_r_brace && self.spread_paren_depth() == 0
    }

    /// Generate a [`Fix`] to remove an unnecessary dictionary spread.
    fn rewrite_spread_item(
        &mut self,
        dict: &ast::ExprDict,
        prev_end: TextSize,
        locator: &Locator,
    ) -> Option<Fix> {
        // Find the `**` token preceding the spread.
        let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
            .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

        if let Some(last) = dict.iter_values().last() {
            // Ex) `**{a: 1, b: 2}`
            self.begin_spread_rewrite();
            for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
                if self.spread_close_complete() {
                    break;
                }
                match tok.kind() {
                    SimpleTokenKind::Comma => {
                        self.push_spread_deletion(tok.range());
                    }
                    SimpleTokenKind::RBrace => {
                        self.push_spread_deletion(tok.range());
                        self.mark_spread_brace_found();
                        break;
                    }
                    _ => {}
                }
            }
            Some(Fix::safe_edits(
                // Delete the first `**{`
                Edit::deletion(doublestar.start(), dict.start() + TextSize::from(1)),
                // Delete the trailing `}`
                self.take_spread_edits(),
            ))
        } else {
            // Ex) `**{}`
            Some(Fix::safe_edit(Edit::deletion(
                doublestar.start(),
                dict.end(),
            )))
        }
    }

    pub(crate) fn rewrite_dict_kwargs(&mut self, checker: &mut Checker, call: &ast::ExprCall) {
        self.reset_keyword_state(call);
        let mut duplicate_keywords = None;
        for keyword in &*call.arguments.keywords {
            match self.classify_keyword_item(keyword) {
                KeywordShape::Named => continue,
                KeywordShape::OtherUnpack => continue,
                KeywordShape::DictUnpack => {}
            }

            let Expr::Dict(dict) = &keyword.value else {
                continue;
            };

            if let [ast::DictItem { key: None, value }] = dict.items.as_slice() {
                let diagnostic = Diagnostic::new(UnnecessaryDictKwargs, keyword.range());
                let edit = Edit::range_replacement(
                    format!("**{}", checker.locator().slice(value)),
                    keyword.range(),
                );
                checker
                    .diagnostics
                    .push(diagnostic.with_fix(Fix::safe_edit(edit)));
                continue;
            }

            self.collect_kwargs_from_dict(dict);
            if self.collected_kwarg_count() != dict.len() {
                continue;
            }

            let mut diagnostic = Diagnostic::new(UnnecessaryDictKwargs, keyword.range());

            if dict.is_empty() {
                diagnostic.try_set_fix(|| {
                    remove_argument(
                        keyword,
                        &call.arguments,
                        Parentheses::Preserve,
                        checker.locator().contents(),
                    )
                    .map(Fix::safe_edit)
                });
            } else {
                if duplicate_keywords.is_none() {
                    duplicate_keywords = Some(self.collect_duplicate_keywords(call));
                }

                if let Some(duplicate_keywords) = duplicate_keywords.as_ref() {
                    if self
                        .collected_kwargs
                        .iter()
                        .all(|kwarg| !duplicate_keywords.contains(kwarg.as_str()))
                    {
                        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                            self.collected_kwargs
                                .iter()
                                .zip(dict.iter_values())
                                .map(|(kwarg, value)| {
                                    format!(
                                        "{}={}",
                                        kwarg,
                                        checker.locator().slice(
                                            parenthesized_range(
                                                value.into(),
                                                dict.into(),
                                                checker.comment_ranges(),
                                                checker.locator().contents(),
                                            )
                                            .unwrap_or(value.range())
                                        )
                                    )
                                })
                                .join(", "),
                            keyword.range(),
                        )));
                    }
                }
            }

            checker.diagnostics.push(diagnostic);
        }
    }

    fn reset_keyword_state(&mut self, call: &ast::ExprCall) {
        self.keyword_seen.clear();
        self.keyword_duplicates.clear();
        self.collected_kwargs.clear();
        self.range_start_is_zero = call.arguments.keywords.is_empty();
    }

    fn classify_keyword_item(&mut self, keyword: &ast::Keyword) -> KeywordShape {
        if keyword.arg.is_some() {
            self.range_start_is_zero = false;
            KeywordShape::Named
        } else if matches!(keyword.value, Expr::Dict(_)) {
            KeywordShape::DictUnpack
        } else {
            KeywordShape::OtherUnpack
        }
    }

    fn collect_kwargs_from_dict(&mut self, dict: &ast::ExprDict) {
        self.collected_kwargs.clear();
        for key in dict.iter_keys() {
            if let Some(name) = key.and_then(as_kwarg) {
                self.collected_kwargs.push(name.to_string());
            }
        }
    }

    fn collect_duplicate_keywords(&mut self, call: &ast::ExprCall) -> FxHashSet<String> {
        self.keyword_seen.clear();
        self.keyword_duplicates.clear();
        for keyword in &*call.arguments.keywords {
            if let Some(name) = &keyword.arg {
                self.record_keyword_name(name.as_str());
            } else if let Expr::Dict(dict) = &keyword.value {
                for key in dict.iter_keys() {
                    if let Some(name) = key.and_then(as_kwarg) {
                        self.record_keyword_name(name);
                    }
                }
            }
        }
        self.keyword_duplicates.clone()
    }

    fn record_keyword_name(&mut self, name: &str) {
        if !self.keyword_seen.insert(name.to_string()) {
            self.keyword_duplicates.insert(name.to_string());
        }
    }


    fn collected_kwarg_count(&self) -> usize {
        self.collected_kwargs.len()
    }

    pub(crate) fn rewrite_range_start(&mut self, checker: &mut Checker, call: &ast::ExprCall) {
        self.range_start_is_zero = false;
        if !call.arguments.keywords.is_empty() {
            return;
        }

        let [start, _] = &*call.arguments.args else {
            return;
        };

        let Expr::NumberLiteral(ast::ExprNumberLiteral {
            value: ast::Number::Int(value),
            ..
        }) = start
        else {
            return;
        };
        self.range_start_is_zero = *value == 0;
        if !self.range_start_is_literal_zero() {
            return;
        }

        if !checker.semantic().match_builtin_expr(&call.func, "range") {
            return;
        }

        let mut diagnostic = Diagnostic::new(UnnecessaryRangeStart, start.range());
        diagnostic.try_set_fix(|| {
            remove_argument(
                &start,
                &call.arguments,
                Parentheses::Preserve,
                checker.locator().contents(),
            )
            .map(Fix::safe_edit)
        });
        checker.diagnostics.push(diagnostic);
    }

    fn range_start_is_literal_zero(&self) -> bool {
        self.range_start_is_zero
    }

    pub(crate) fn rewrite_key_in_dict(
        &mut self,
        checker: &mut Checker,
        left: &Expr,
        right: &Expr,
        operator: CmpOp,
        parent: AnyNodeRef,
    ) {
        self.reset_membership_state(operator);
        let Expr::Call(ast::ExprCall {
            func,
            arguments: Arguments { args, keywords, .. },
            range: _,
        }) = &right
        else {
            return;
        };
        if !(args.is_empty() && keywords.is_empty()) {
            return;
        }

        let Expr::Attribute(ast::ExprAttribute { attr, value, .. }) = func.as_ref() else {
            return;
        };
        if !self.membership_is_keys_attr(attr.as_str()) {
            return;
        }

        if value
            .as_name_expr()
            .is_some_and(|name| matches!(name.id.as_str(), "self"))
        {
            return;
        }

        let left_range = parenthesized_range(
            left.into(),
            parent,
            checker.comment_ranges(),
            checker.locator().contents(),
        )
        .unwrap_or(left.range());
        let right_range = parenthesized_range(
            right.into(),
            parent,
            checker.comment_ranges(),
            checker.locator().contents(),
        )
        .unwrap_or(right.range());

        let mut diagnostic = Diagnostic::new(
            InDictKeys {
                operator: self.membership_operator.clone(),
            },
            TextRange::new(left_range.start(), right_range.end()),
        );
        if let Some(dot) = SimpleTokenizer::starts_at(value.end(), checker.locator().contents())
            .skip_trivia()
            .find(|token| token.kind == SimpleTokenKind::Dot)
        {
            let applicability = {
                let is_dict = value.as_name_expr().is_some_and(|name| {
                    let Some(binding) = checker
                        .semantic()
                        .only_binding(name)
                        .map(|id| checker.semantic().binding(id))
                    else {
                        return false;
                    };
                    typing::is_dict(binding, checker.semantic())
                });
                if is_dict {
                    Applicability::Safe
                } else {
                    Applicability::Unsafe
                }
            };

            let range = TextRange::new(dot.start(), right.end());
            self.membership_insert_space = checker
                .locator()
                .after(range.end())
                .chars()
                .next()
                .is_some_and(|char| char.is_ascii_alphabetic());
            if self.membership_insert_space {
                diagnostic.set_fix(Fix::applicable_edit(
                    Edit::range_replacement(" ".to_string(), range),
                    applicability,
                ));
            } else {
                diagnostic.set_fix(Fix::applicable_edit(
                    Edit::range_deletion(range),
                    applicability,
                ));
            }
        }
        checker.diagnostics.push(diagnostic);
    }

    fn reset_membership_state(&mut self, operator: CmpOp) {
        self.membership_operator = operator.as_str().to_string();
        self.membership_insert_space = false;
        self.lookup_value_name.clear();
        self.zip_expected.clear();
    }

    fn membership_is_keys_attr(&self, attr: &str) -> bool {
        attr == "keys" && !self.membership_operator.is_empty()
    }

    pub(crate) fn rewrite_key_in_dict_for(&mut self, checker: &mut Checker, for_stmt: &ast::StmtFor) {
        self.reset_membership_state(CmpOp::In);
        self.rewrite_key_in_dict(
            checker,
            &for_stmt.target,
            &for_stmt.iter,
            CmpOp::In,
            for_stmt.into(),
        );
    }

    pub(crate) fn rewrite_key_in_dict_comprehension(
        &mut self,
        checker: &mut Checker,
        comprehension: &Comprehension,
    ) {
        self.reset_membership_state(CmpOp::In);
        self.rewrite_key_in_dict(
            checker,
            &comprehension.target,
            &comprehension.iter,
            CmpOp::In,
            comprehension.into(),
        );
    }

    pub(crate) fn rewrite_key_in_dict_compare(
        &mut self,
        checker: &mut Checker,
        compare: &ast::ExprCompare,
    ) {
        let [op] = &*compare.ops else {
            return;
        };

        if !matches!(op, CmpOp::In | CmpOp::NotIn) {
            return;
        }

        let [right] = &*compare.comparators else {
            return;
        };

        self.reset_membership_state(*op);
        self.rewrite_key_in_dict(checker, &compare.left, right, *op, compare.into());
    }

    pub(crate) fn rewrite_zip_dict_keys_and_values(
        &mut self,
        checker: &mut Checker,
        expr: &ast::ExprCall,
    ) {
        self.zip_expected.clear();
        let ast::ExprCall {
            func,
            arguments: Arguments { args, keywords, .. },
            ..
        } = expr;
        match &keywords[..] {
            [] => {}
            [ast::Keyword {
                arg: Some(name), ..
            }] if name.as_str() == "strict" => {}
            _ => return,
        };
        let [arg1, arg2] = &args[..] else {
            return;
        };
        let Some((var1, attr1)) = zip_var_attr(arg1) else {
            return;
        };
        let Some((var2, attr2)) = zip_var_attr(arg2) else {
            return;
        };
        if var1.id != var2.id || attr1 != "keys" || attr2 != "values" {
            return;
        }
        if !checker.semantic().match_builtin_expr(func, "zip") {
            return;
        }

        let Some(binding) = checker
            .semantic()
            .only_binding(var1)
            .map(|id| checker.semantic().binding(id))
        else {
            return;
        };
        if !typing::is_dict(binding, checker.semantic()) {
            return;
        }

        self.zip_expected = format!("{}.items()", checker.locator().slice(var1));
        let actual = checker.locator().slice(expr);

        let mut diagnostic = Diagnostic::new(
            ZipDictKeysAndValues {
                expected: SourceCodeSnippet::new(self.zip_expected.clone()),
                actual: SourceCodeSnippet::from_str(actual),
            },
            expr.range(),
        );
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            self.zip_expected.clone(),
            expr.range(),
        )));
        checker.diagnostics.push(diagnostic);
    }


    pub(crate) fn rewrite_dict_index_lookup(&mut self, checker: &mut Checker, stmt_for: &StmtFor) {
        self.lookup_value_name.clear();
        let Some((dict_name, index_name, value_name)) =
            self.dict_items(&stmt_for.iter, &stmt_for.target)
        else {
            return;
        };
        self.lookup_value_name = value_name.id.to_string();

        let ranges = {
            let mut visitor = SequenceIndexVisitor::new(&dict_name.id, &index_name.id, &value_name.id);
            visitor.visit_body(&stmt_for.body);
            visitor.visit_body(&stmt_for.orelse);
            visitor.into_accesses()
        };

        self.emit_dict_index_diagnostics(checker, ranges, index_name, value_name);
    }

    pub(crate) fn rewrite_dict_index_lookup_comprehension(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
    ) {
        self.lookup_value_name.clear();
        let (Expr::Generator(ast::ExprGenerator {
            elt, generators, ..
        })
        | Expr::DictComp(ast::ExprDictComp {
            value: elt,
            generators,
            ..
        })
        | Expr::SetComp(ast::ExprSetComp {
            elt, generators, ..
        })
        | Expr::ListComp(ast::ExprListComp {
            elt, generators, ..
        })) = expr
        else {
            return;
        };

        for comp in generators {
            let Some((dict_name, index_name, value_name)) =
                self.dict_items(&comp.iter, &comp.target)
            else {
                continue;
            };
            self.lookup_value_name = value_name.id.to_string();

            let ranges = {
                let mut visitor =
                    SequenceIndexVisitor::new(&dict_name.id, &index_name.id, &value_name.id);
                visitor.visit_expr(elt.as_ref());
                for expr in &comp.ifs {
                    visitor.visit_expr(expr);
                }
                visitor.into_accesses()
            };

            self.emit_dict_index_diagnostics(checker, ranges, index_name, value_name);
        }
    }

    fn emit_dict_index_diagnostics(
        &mut self,
        checker: &mut Checker,
        ranges: Vec<TextRange>,
        index_name: &ast::ExprName,
        value_name: &ast::ExprName,
    ) {
        for range in ranges {
            let mut diagnostic = Diagnostic::new(UnnecessaryDictIndexLookup, range);
            diagnostic.set_fix(Fix::safe_edits(
                Edit::range_replacement(self.lookup_value_name.clone(), range),
                [self.noop_name(index_name), self.noop_name(value_name)],
            ));
            checker.diagnostics.push(diagnostic);
        }
    }

    fn dict_items<'a>(
        &mut self,
        call_expr: &'a Expr,
        tuple_expr: &'a Expr,
    ) -> Option<(&'a ast::ExprName, &'a ast::ExprName, &'a ast::ExprName)> {
        self.lookup_value_name.clear();
        let ast::ExprCall {
            func, arguments, ..
        } = call_expr.as_call_expr()?;

        if !arguments.is_empty() {
            return None;
        }
        let Expr::Attribute(ast::ExprAttribute { value, attr, .. }) = func.as_ref() else {
            return None;
        };
        if attr != "items" {
            return None;
        }

        let Expr::Name(dict_name) = value.as_ref() else {
            return None;
        };

        let Expr::Tuple(ast::ExprTuple { elts, .. }) = tuple_expr else {
            return None;
        };
        let [index, value] = elts.as_slice() else {
            return None;
        };

        let Expr::Name(index_name) = index else {
            return None;
        };

        let Expr::Name(value_name) = value else {
            return None;
        };

        if index_name.id == "_" || value_name.id == "_" {
            return None;
        }

        Some((dict_name, index_name, value_name))
    }

    fn noop_name(&self, name: &ast::ExprName) -> Edit {
        if self.lookup_value_name == name.id.as_str() {
            Edit::range_replacement(self.lookup_value_name.clone(), name.range())
        } else {
            Edit::range_replacement(name.id.to_string(), name.range())
        }
    }

    fn note_body_event(&mut self) {
        self.body_event_count = self.body_event_count.saturating_add(1);
    }

    fn note_literal_rewrite(&mut self) {
        self.literal_rewrite_count = self.literal_rewrite_count.saturating_add(1);
    }

    pub(crate) fn rewrite_placeholders(&mut self, checker: &mut Checker, body: &[Stmt]) {
        self.note_body_event();
        self.placeholder_kind_pass = false;
        if body.len() < 2 {
            return;
        }

        for (index, stmt) in body.iter().enumerate() {
            let kind = match stmt {
                Stmt::Pass(_) => {
                    self.placeholder_kind_pass = true;
                    Placeholder::Pass
                }
                Stmt::Expr(expr) if expr.value.is_ellipsis_literal_expr() => {
                    self.placeholder_kind_pass = false;
                    if checker.semantic().in_type_checking_block() {
                        return;
                    }
                    if in_protocol_or_abstract_method(checker.semantic()) {
                        return;
                    }
                    Placeholder::Ellipsis
                }
                _ => continue,
            };

            let next_stmt = body.get(index + 1);
            self.emit_placeholder_diagnostic(checker, stmt, next_stmt, kind);
        }
    }

    fn emit_placeholder_diagnostic(
        &mut self,
        checker: &mut Checker,
        stmt: &Stmt,
        next_stmt: Option<&Stmt>,
        placeholder_kind: Placeholder,
    ) {
        self.note_body_event();
        self.placeholder_kind_pass = matches!(placeholder_kind, Placeholder::Pass);
        let edit = if let Some(index) = trailing_comment_start_offset(stmt, checker.source()) {
            Edit::range_deletion(stmt.range().add_end(index))
        } else {
            fix::edits::delete_stmt(stmt, None, checker.locator(), checker.indexer())
        };
        let applicability = match next_stmt {
            Some(Stmt::Expr(StmtExpr { value, .. })) => match value.as_ref() {
                Expr::StringLiteral(ExprStringLiteral { .. }) => Applicability::Unsafe,
                _ => Applicability::Safe,
            },
            _ => Applicability::Safe,
        };

        let isolation_level = Checker::isolation(checker.semantic().current_statement_id());
        let fix = Fix::applicable_edit(edit, applicability).isolate(isolation_level);

        let diagnostic = Diagnostic::new(
            UnnecessaryPlaceholder {
                kind: placeholder_kind,
            },
            stmt.range(),
        );

        checker.diagnostics.push(diagnostic.with_fix(fix));
    }


    pub(crate) fn rewrite_duplicate_fields(&mut self, checker: &mut Checker, body: &[Stmt]) {
        self.note_body_event();
        self.seen_field_names.clear();
        for stmt in body {
            let target = match stmt {
                Stmt::Assign(ast::StmtAssign { targets, .. }) => {
                    if let [Expr::Name(id)] = targets.as_slice() {
                        id
                    } else {
                        continue;
                    }
                }
                Stmt::AnnAssign(ast::StmtAnnAssign { target, .. }) => {
                    if let Expr::Name(id) = target.as_ref() {
                        id
                    } else {
                        continue;
                    }
                }
                _ => continue,
            };

            match stmt {
                Stmt::Assign(ast::StmtAssign { value, .. }) => {
                    if any_over_expr(value.as_ref(), &|expr| {
                        expr.as_name_expr().is_some_and(|name| name.id == target.id)
                    }) {
                        continue;
                    }
                }
                Stmt::AnnAssign(ast::StmtAnnAssign {
                    value: Some(value), ..
                }) => {
                    if any_over_expr(value.as_ref(), &|expr| {
                        expr.as_name_expr().is_some_and(|name| name.id == target.id)
                    }) {
                        continue;
                    }
                }
                _ => continue,
            }

            if self.has_seen_field(target.id.as_str()) {
                let mut diagnostic = Diagnostic::new(
                    DuplicateClassFieldDefinition {
                        name: target.id.to_string(),
                    },
                    stmt.range(),
                );
                let edit =
                    fix::edits::delete_stmt(stmt, Some(stmt), checker.locator(), checker.indexer());
                diagnostic.set_fix(Fix::unsafe_edit(edit).isolate(Checker::isolation(
                    checker.semantic().current_statement_id(),
                )));
                checker.diagnostics.push(diagnostic);
            } else {
                self.seen_field_names.insert(target.id.to_string());
            }
        }
    }

    fn has_seen_field(&self, name: &str) -> bool {
        self.seen_field_names.contains(name)
    }

    pub(crate) fn rewrite_non_unique_enums(
        &mut self,
        checker: &mut Checker,
        parent: &Stmt,
        body: &[Stmt],
    ) {
        self.note_body_event();
        self.enum_value_keys.clear();
        let semantic = checker.semantic();

        let Stmt::ClassDef(parent) = parent else {
            return;
        };

        if !parent.bases().iter().any(|expr| {
            semantic
                .resolve_qualified_name(expr)
                .is_some_and(|qualified_name| matches!(qualified_name.segments(), ["enum", "Enum"]))
        }) {
            return;
        }

        let mut seen_targets: FxHashSet<ComparableExpr> = FxHashSet::default();
        for stmt in body {
            let Stmt::Assign(ast::StmtAssign { value, .. }) = stmt else {
                continue;
            };

            if let Expr::Call(ast::ExprCall { func, .. }) = value.as_ref() {
                if checker
                    .semantic()
                    .resolve_qualified_name(func)
                    .is_some_and(|qualified_name| {
                        matches!(qualified_name.segments(), ["enum", "auto"])
                    })
                {
                    continue;
                }
            }

            if checker.source_type.is_stub() && member_has_unknown_value(checker, value) {
                continue;
            }

            let comparable = ComparableExpr::from(value);

            if !seen_targets.insert(comparable) {
                let rendered = checker.generator().expr(value);
                self.enum_value_keys.insert(rendered.clone());
                let diagnostic = Diagnostic::new(
                    NonUniqueEnums { value: rendered },
                    stmt.range(),
                );
                checker.diagnostics.push(diagnostic);
            }
        }
    }


    pub(crate) fn rewrite_container_builtin(
        &mut self,
        checker: &mut Checker,
        expr: &ast::ExprLambda,
    ) {
        self.note_literal_rewrite();
        self.dict_call_kind = 0;
        let ast::ExprLambda {
            parameters,
            body,
            range: _,
        } = expr;

        if parameters.is_some() {
            return;
        }

        let container = match &**body {
            Expr::List(list) if list.is_empty() => {
                self.dict_call_kind = 1;
                Container::List
            }
            Expr::Dict(dict) if dict.is_empty() => {
                self.dict_call_kind = 2;
                Container::Dict
            }
            _ => return,
        };
        let mut diagnostic = Diagnostic::new(ReimplementedContainerBuiltin { container }, expr.range());
        diagnostic.try_set_fix(|| {
            let (import_edit, binding) = checker.importer().get_or_import_builtin_symbol(
                container.as_str(),
                expr.start(),
                checker.semantic(),
            )?;
            let binding_edit = Edit::range_replacement(binding, expr.range());
            Ok(Fix::safe_edits(binding_edit, import_edit))
        });
        checker.diagnostics.push(diagnostic);
    }

    pub(crate) fn rewrite_multiple_starts_ends_with(&mut self, checker: &mut Checker, expr: &Expr) {
        self.note_body_event();
        self.starts_indices.clear();
        let Expr::BoolOp(ast::ExprBoolOp {
            op: BoolOp::Or,
            values,
            range: _,
        }) = expr
        else {
            return;
        };

        let mut duplicates = BTreeMap::new();
        for (index, call) in values.iter().enumerate() {
            let Expr::Call(ast::ExprCall {
                func,
                arguments:
                    Arguments {
                        args,
                        keywords,
                        range: _,
                    },
                range: _,
            }) = &call
            else {
                continue;
            };

            if !keywords.is_empty() {
                continue;
            }

            let [arg] = &**args else {
                continue;
            };

            let Expr::Attribute(ast::ExprAttribute { value, attr, .. }) = func.as_ref() else {
                continue;
            };
            if attr != "startswith" && attr != "endswith" {
                continue;
            }

            let Expr::Name(ast::ExprName { id: arg_name, .. }) = value.as_ref() else {
                continue;
            };

            if is_bound_to_tuple(arg, checker.semantic()) {
                continue;
            }

            duplicates
                .entry((attr.as_str(), arg_name.as_str()))
                .or_insert_with(Vec::new)
                .push(index);
        }

        for ((attr_name, arg_name), indices) in duplicates {
            self.starts_indices = indices.clone();
            if self.starts_indices.len() > 1 {
                self.emit_merged_starts_ends(
                    checker,
                    expr,
                    values,
                    attr_name,
                    arg_name,
                );
            }
        }
    }

    fn emit_merged_starts_ends(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
        values: &[Expr],
        attr_name: &str,
        arg_name: &str,
    ) {
        self.note_body_event();
        let indices = &self.starts_indices;
        let mut diagnostic = Diagnostic::new(
            MultipleStartsEndsWith {
                attr: attr_name.to_string(),
            },
            expr.range(),
        );
        let words: Vec<&Expr> = indices
            .iter()
            .map(|index| &values[*index])
            .map(|expr| {
                let Expr::Call(ast::ExprCall {
                    func: _,
                    arguments:
                        Arguments {
                            args,
                            keywords: _,
                            range: _,
                        },
                    range: _,
                }) = expr
                else {
                    unreachable!(
                        "{}",
                        format!("Indices should only contain `{attr_name}` calls")
                    )
                };
                args.first()
                    .unwrap_or_else(|| panic!("`{attr_name}` should have one argument"))
            })
            .collect();

        let node = Expr::Tuple(ast::ExprTuple {
            elts: words
                .iter()
                .flat_map(|value| {
                    if let Expr::Tuple(tuple) = value {
                        Left(tuple.iter())
                    } else {
                        Right(iter::once(*value))
                    }
                })
                .cloned()
                .collect(),
            ctx: ExprContext::Load,
            range: TextRange::default(),
            parenthesized: true,
        });
        let node1 = Expr::Name(ast::ExprName {
            id: arg_name.into(),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        });
        let node2 = Expr::Attribute(ast::ExprAttribute {
            value: Box::new(node1),
            attr: Identifier::new(attr_name.to_string(), TextRange::default()),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        });
        let node3 = Expr::Call(ast::ExprCall {
            func: Box::new(node2),
            arguments: Arguments {
                args: Box::from([node]),
                keywords: Box::from([]),
                range: TextRange::default(),
            },
            range: TextRange::default(),
        });
        let call = node3;

        let mut call = Some(call);
        let node = Expr::BoolOp(ast::ExprBoolOp {
            op: BoolOp::Or,
            values: values
                .iter()
                .enumerate()
                .filter_map(|(index, elt)| {
                    if indices.contains(&index) {
                        std::mem::take(&mut call)
                    } else {
                        Some(elt.clone())
                    }
                })
                .collect(),
            range: TextRange::default(),
        });
        let bool_op = node;
        diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
            checker.generator().expr(&bool_op),
            expr.range(),
        )));
        checker.diagnostics.push(diagnostic);
    }


    pub(crate) fn rewrite_literal_dict(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
        func: &Expr,
        args: &[Expr],
        keywords: &[Keyword],
    ) {
        self.note_literal_rewrite();
        self.literal_kind_is_list = false;
        self.literal_pair_count = 0;
        let Some(argument) =
            self.exactly_one_argument_with_matching_function("dict", func, args, keywords)
        else {
            return;
        };
        let elts = match argument {
            Expr::Tuple(ast::ExprTuple { elts, .. }) => {
                self.literal_kind_is_list = false;
                elts
            }
            Expr::List(ast::ExprList { elts, .. }) => {
                self.literal_kind_is_list = true;
                elts
            }
            _ => return,
        };
        let kind = if self.literal_rewrites_list() {
            LiteralKind::List
        } else {
            LiteralKind::Tuple
        };
        self.literal_pair_count = elts.len();
        if !elts
            .iter()
            .all(|elt| matches!(&elt, Expr::Tuple(tuple) if tuple.len() == 2))
        {
            return;
        }
        if !checker.semantic().has_builtin_binding("dict") {
            return;
        }
        let mut diagnostic = Diagnostic::new(UnnecessaryLiteralDict { obj_type: kind }, expr.range());
        diagnostic
            .try_set_fix(|| fixes::fix_unnecessary_literal_dict(expr, checker).map(Fix::unsafe_edit));
        checker.diagnostics.push(diagnostic);
    }

    pub(crate) fn rewrite_literal_within_dict_call(
        &mut self,
        checker: &mut Checker,
        call: &ast::ExprCall,
    ) {
        self.note_literal_rewrite();
        self.dict_call_kind = 0;
        if !call.arguments.keywords.is_empty() {
            return;
        }
        let Some(argument) =
            self.first_argument_with_matching_function("dict", &call.func, &call.arguments.args)
        else {
            return;
        };
        let Some(argument_kind) = DictKind::try_from_expr(argument) else {
            return;
        };
        self.dict_call_kind = match argument_kind {
            DictKind::Literal => 1,
            DictKind::Comprehension => 2,
        };
        if !checker.semantic().has_builtin_binding("dict") {
            return;
        }

        let mut diagnostic = Diagnostic::new(
            UnnecessaryLiteralWithinDictCall {
                kind: argument_kind,
            },
            call.range(),
        );

        diagnostic.set_fix({
            let call_start = Edit::deletion(call.start(), argument.start());
            let call_end = Edit::deletion(argument.end(), call.end());
            Fix::unsafe_edits(call_start, [call_end])
        });

        checker.diagnostics.push(diagnostic);
    }

    pub(crate) fn rewrite_generator_dict(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
        func: &Expr,
        args: &[Expr],
        keywords: &[Keyword],
    ) {
        self.note_literal_rewrite();
        self.literal_pair_count = 0;
        let Some(argument) =
            self.exactly_one_argument_with_matching_function("dict", func, args, keywords)
        else {
            return;
        };
        let Expr::Generator(ast::ExprGenerator { elt, .. }) = argument else {
            return;
        };
        let Expr::Tuple(tuple) = &**elt else {
            return;
        };
        self.literal_pair_count = tuple.len();
        if self.literal_pair_count != 2 {
            return;
        }
        if tuple.iter().any(Expr::is_starred_expr) {
            return;
        }
        let mut diagnostic = Diagnostic::new(UnnecessaryGeneratorDict, expr.range());
        diagnostic
            .try_set_fix(|| fixes::fix_unnecessary_generator_dict(expr, checker).map(Fix::unsafe_edit));
        checker.diagnostics.push(diagnostic);
    }

    pub(crate) fn rewrite_list_comprehension_dict(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
        func: &Expr,
        args: &[Expr],
        keywords: &[Keyword],
    ) {
        self.note_literal_rewrite();
        self.literal_pair_count = 0;
        let Some(argument) =
            self.exactly_one_argument_with_matching_function("dict", func, args, keywords)
        else {
            return;
        };
        let Expr::ListComp(ast::ExprListComp { elt, .. }) = argument else {
            return;
        };
        let Expr::Tuple(tuple) = &**elt else {
            return;
        };
        self.literal_pair_count = tuple.len();
        if self.literal_pair_count != 2 {
            return;
        }
        if !checker.semantic().has_builtin_binding("dict") {
            return;
        }
        let mut diagnostic = Diagnostic::new(UnnecessaryListComprehensionDict, expr.range());
        diagnostic.try_set_fix(|| {
            fixes::fix_unnecessary_list_comprehension_dict(expr, checker).map(Fix::unsafe_edit)
        });
        checker.diagnostics.push(diagnostic);
    }

    pub(crate) fn rewrite_dict_comprehension_for_iterable(
        &mut self,
        checker: &mut Checker,
        dict_comp: &ast::ExprDictComp,
    ) {
        self.note_literal_rewrite();
        self.fromkeys_value_is_none = false;
        let [generator] = dict_comp.generators.as_slice() else {
            return;
        };

        if !generator.ifs.is_empty() {
            return;
        }
        if generator.is_async {
            return;
        }

        if ComparableExpr::from(&generator.target) != ComparableExpr::from(dict_comp.key.as_ref()) {
            return;
        }

        if !is_constant_like(dict_comp.value.as_ref()) {
            return;
        }

        let self_referential = any_over_expr(dict_comp.value.as_ref(), &|expr| {
            let Expr::Name(name) = expr else {
                return false;
            };

            let Some(id) = checker.semantic().resolve_name(name) else {
                return false;
            };

            let binding = checker.semantic().binding(id);

            dict_comp.range().contains_range(binding.range())
        });
        if self_referential {
            return;
        }

        self.fromkeys_value_is_none = dict_comp.value.is_none_literal_expr();
        let mut diagnostic = Diagnostic::new(
            UnnecessaryDictComprehensionForIterable {
                is_value_none_literal: self.fromkeys_uses_none(),
            },
            dict_comp.range(),
        );

        if checker.semantic().has_builtin_binding("dict") {
            diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                checker
                    .generator()
                    .expr(&self.fix_unnecessary_dict_comprehension(
                        dict_comp.value.as_ref(),
                        generator,
                    )),
                dict_comp.range(),
            )));
        }

        checker.diagnostics.push(diagnostic);
    }


    fn fix_unnecessary_dict_comprehension(&self, value: &Expr, generator: &Comprehension) -> Expr {
        let iterable = generator.iter.clone();
        let args = Arguments {
            args: if self.fromkeys_uses_none() {
                Box::from([iterable])
            } else {
                Box::from([iterable, value.clone()])
            },
            keywords: Box::from([]),
            range: TextRange::default(),
        };
        Expr::Call(ExprCall {
            func: Box::new(Expr::Name(ast::ExprName {
                id: "dict.fromkeys".into(),
                ctx: ExprContext::Load,
                range: TextRange::default(),
            })),
            arguments: args,
            range: TextRange::default(),
        })
    }

    fn exactly_one_argument_with_matching_function<'a>(
        &mut self,
        name: &str,
        func: &Expr,
        args: &'a [Expr],
        keywords: &[Keyword],
    ) -> Option<&'a Expr> {
        self.literal_pair_count = args.len();
        let [arg] = args else {
            return None;
        };
        if !keywords.is_empty() {
            return None;
        }
        let func = func.as_name_expr()?;
        if func.id != name {
            return None;
        }
        Some(arg)
    }

    fn first_argument_with_matching_function<'a>(
        &mut self,
        name: &str,
        func: &Expr,
        args: &'a [Expr],
    ) -> Option<&'a Expr> {
        self.literal_pair_count = args.len();
        if func.as_name_expr().is_some_and(|func| func.id == name) {
            args.first()
        } else {
            None
        }
    }

    fn literal_rewrites_list(&self) -> bool {
        self.literal_kind_is_list
    }

    fn fromkeys_uses_none(&self) -> bool {
        self.fromkeys_value_is_none
    }
}

fn as_kwarg(key: &Expr) -> Option<&str> {
    if let Expr::StringLiteral(ast::ExprStringLiteral { value, .. }) = key {
        if is_identifier(value.to_str()) {
            return Some(value.to_str());
        }
    }
    None
}

fn zip_var_attr(expr: &Expr) -> Option<(&ast::ExprName, &Identifier)> {
    let Expr::Call(ast::ExprCall { func, .. }) = expr else {
        return None;
    };
    let Expr::Attribute(ast::ExprAttribute { value, attr, .. }) = func.as_ref() else {
        return None;
    };
    let Expr::Name(var_name) = value.as_ref() else {
        return None;
    };
    Some((var_name, attr))
}

fn in_protocol_or_abstract_method(semantic: &SemanticModel) -> bool {
    semantic.current_scopes().any(|scope| match scope.kind {
        ScopeKind::Class(class_def) => class_def
            .bases()
            .iter()
            .any(|base| semantic.match_typing_expr(map_subscript(base), "Protocol")),
        ScopeKind::Function(function_def) => {
            ruff_python_semantic::analyze::visibility::is_abstract(
                &function_def.decorator_list,
                semantic,
            )
        }
        _ => false,
    })
}

fn member_has_unknown_value(checker: &Checker, expr: &Expr) -> bool {
    match expr {
        Expr::EllipsisLiteral(_) => true,
        Expr::Call(ExprCall {
            func, arguments, ..
        }) => {
            if !checker.semantic().match_typing_expr(func, "cast") {
                return false;
            }
            if !arguments.keywords.is_empty() {
                return false;
            }
            matches!(arguments.args.as_ref(), [_, Expr::EllipsisLiteral(_)])
        }
        _ => false,
    }
}

fn is_bound_to_tuple(arg: &Expr, semantic: &SemanticModel) -> bool {
    let Expr::Name(ast::ExprName { id, .. }) = arg else {
        return false;
    };

    let Some(binding_id) = semantic.lookup_symbol(id.as_str()) else {
        return false;
    };

    let binding = semantic.binding(binding_id);

    analyze::typing::is_tuple(binding, semantic)
}

fn is_constant_like(expr: &Expr) -> bool {
    !any_over_expr(expr, &|expr| {
        matches!(
            expr,
            Expr::Lambda(_)
                | Expr::List(_)
                | Expr::Dict(_)
                | Expr::Set(_)
                | Expr::ListComp(_)
                | Expr::SetComp(_)
                | Expr::DictComp(_)
                | Expr::Generator(_)

