                }
                SimpleTokenKind::RBrace => {
                    self.push_spread_deletion(tok.range());
                    self.mark_spread_brace_found();
                }
                _ => {}
            }
        }
    }

    let mut edits = self.take_spread_edits();
    let first = edits.pop()?;
    Some(Fix::safe_edits(first, edits))
}

