   /// Generate a [`Fix`] to remove an unnecessary dictionary spread.
   fn rewrite_spread_item(
       &mut self,
       dict: &ast::ExprDict,
       prev_end: TextSize,
       locator: &Locator,
   ) -> Option<Fix> {
       // Find the `**` token preceding the spread.
       let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
           .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

       self.begin_spread_rewrite();

       // Delete the `**`, any parentheses wrapping the dictionary, and the
       // opening brace. Comments are preserved.
       let mut open_parens = 0;
       for tok in SimpleTokenizer::starts_at(doublestar.start(), locator.contents()).skip_trivia()
       {
           if tok.start() > dict.start() {
               break;
           }
           match tok.kind() {
               SimpleTokenKind::LParen => {
                   open_parens += 1;
                   self.push_spread_deletion(tok.range());
               }
               SimpleTokenKind::DoubleStar | SimpleTokenKind::LBrace => {
                   self.push_spread_deletion(tok.range());
               }
               _ => {}
           }
           if tok.start() >= dict.start() {
               break;
           }
       }

       // Delete a trailing comma, the closing brace, and any parentheses that
       // wrap the dictionary. Comments are preserved.
       let scan_start = dict
           .iter_values()
           .last()
           .map_or(dict.start() + TextSize::from(1), Ranged::end);
       for tok in SimpleTokenizer::starts_at(scan_start, locator.contents()).skip_trivia() {
           if self.spread_found_r_brace {
               if open_parens == 0 {
                   break;
               }
               if matches!(tok.kind(), SimpleTokenKind::RParen) {
                   open_parens -= 1;
                   self.push_spread_deletion(tok.range());
               } else {
                   break;
               }
           } else {
               match tok.kind() {
                   SimpleTokenKind::Comma => {
                       self.push_spread_deletion(tok.range());
                   }
                   SimpleTokenKind::RBrace => {
                       self.push_spread_deletion(tok.range());
                       self.mark_spread_brace_found();
                   }
                   _ => {}
               }
           }
       }

       let mut edits = self.take_spread_edits();
       let first = edits.pop()?;
       Some(Fix::safe_edits(first, edits))
   }

